# -*- coding: utf-8 -*-
"""更新 references/tuiyan_pool_state.md：消费台账 +3 行，并追加本场留痕。"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = os.path.join(ROOT, "references", "tuiyan_pool_state.md")
text = open(P, encoding="utf-8").read()
lines = text.split("\n")

rows = [
    "| 2026-10-17 | 美与真（道家无用之大用 vs 康德审美 vs 佛缘起） | **采纳为 P37**（白天批处理 10:00 · 本机 ollama qwen3:14b 承担核心推理） |",
    "| 2026-10-17 | 未来与人类（技术奇点 vs 大同 vs 演化远景） | **采纳为 P38**（白天批处理 10:00 · 本机 ollama qwen3:14b 承担核心推理） |",
    "| 2026-10-17 | 善恶之源（性善性恶 vs 演化合作 vs 功利后果） | **采纳为 P39**（白天批处理 10:00 · 本机 ollama qwen3:14b 承担核心推理） |",
]

# 找到表格最后一行（以 | 2026 开头）并追加
last = max(i for i, l in enumerate(lines) if l.startswith("| 2026"))
